"use client";

import { MapPin, MessageSquare, Phone, Truck, User } from "lucide-react";
import { useTranslations } from "next-intl";
import { useState } from "react";
import { useRouter } from "@/i18n/routing";

export function CheckoutForm({ locale = "uk" }: { locale?: string }) {
  const t = useTranslations("checkout");
  const router = useRouter();
  const [err, setErr] = useState("");

  const field = "h-12 rounded-lg border border-black/10 bg-white px-4 text-sm outline-none focus:border-ink";
  const copy = {
    contacts: locale === "ru" ? "Контакты получателя" : locale === "en" ? "Recipient contacts" : "Контакти отримувача",
    shipping: locale === "ru" ? "Куда отправлять" : locale === "en" ? "Shipping destination" : "Куди відправляти",
    payment: locale === "ru" ? "Оплата и комментарий" : locale === "en" ? "Payment and comment" : "Оплата і коментар",
    error:
      locale === "ru"
        ? "Проверьте контактные данные, доставку и наличие товаров в корзине."
        : locale === "en"
          ? "Check contact details, delivery fields and cart availability."
          : "Перевірте контактні дані, доставку та наявність товарів у кошику.",
  };

  return (
    <form
      className="mt-8 grid gap-5"
      onSubmit={async (e) => {
        e.preventDefault();
        setErr("");
        const fd = new FormData(e.currentTarget);
        const res = await fetch("/api/orders", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            name: fd.get("name"),
            phone: fd.get("phone"),
            email: fd.get("email"),
            city: fd.get("city"),
            deliveryMethod: fd.get("deliveryMethod"),
            warehouse: fd.get("warehouse"),
            paymentMethod: fd.get("paymentMethod"),
            comment: fd.get("comment"),
            agree: fd.get("agree") === "on",
          }),
        });
        if (!res.ok) {
          setErr(copy.error);
          return;
        }
        const data = await res.json();
        router.push(`/checkout/success?n=${data.number}`);
      }}
    >
      <section className="rounded-lg border border-black/10 bg-white p-5 shadow-card">
        <div className="mb-4 flex items-center gap-2 font-semibold">
          <User size={18} />
          {copy.contacts}
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <input name="name" required placeholder={t("name")} className={field} />
          <input name="phone" required placeholder={t("phone")} className={field} />
          <input name="email" type="email" placeholder={t("email")} className={`${field} sm:col-span-2`} />
        </div>
      </section>

      <section className="rounded-lg border border-black/10 bg-white p-5 shadow-card">
        <div className="mb-4 flex items-center gap-2 font-semibold">
          <Truck size={18} />
          {copy.shipping}
        </div>
        <div className="grid gap-3">
          <select name="deliveryMethod" className={field}>
            <option value="nova_poshta">{t("np")}</option>
          </select>
          <div className="relative">
            <MapPin className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-graphite/40" size={17} />
            <input name="city" required placeholder={t("city")} className={`${field} w-full pl-11`} />
          </div>
          <input name="warehouse" required placeholder={t("warehouse")} className={field} />
        </div>
      </section>

      <section className="rounded-lg border border-black/10 bg-white p-5 shadow-card">
        <div className="mb-4 flex items-center gap-2 font-semibold">
          <Phone size={18} />
          {copy.payment}
        </div>
        <div className="grid gap-3">
          <select name="paymentMethod" className={field}>
            <option value="cod">{t("cod")}</option>
            <option value="online">{t("online")}</option>
          </select>
          <div className="relative">
            <MessageSquare className="pointer-events-none absolute left-4 top-4 text-graphite/40" size={17} />
            <textarea name="comment" placeholder={t("comment")} className="min-h-28 rounded-lg border border-black/10 bg-white py-3 pl-11 pr-4 text-sm outline-none focus:border-ink" />
          </div>
        </div>
      </section>

      <label className="flex items-start gap-2 text-sm text-graphite/70">
        <input type="checkbox" name="agree" required className="mt-1 accent-black" />
        {t("agree")}
      </label>
      {err && <p className="rounded-lg bg-red-50 p-3 text-sm text-red-700">{err}</p>}
      <button className="rounded-full bg-accent px-6 py-4 text-sm font-semibold text-white transition hover:bg-accentHover">{t("submit")}</button>
    </form>
  );
}
